export function Preloading({
  resourceType = "{{resourceType}}",
  earlyHint = {{earlyHint}},
  accent = "{{accent}}",
}) {
  const names = { "hero-image": "hero-image.jpg", font: "display-font.woff2", script: "app-bundle.js" };
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}><span style={{ width: 90, flex: "none" }}>Document</span><span style={{ display: "block", height: 8, width: "20%", background: "#24143022", borderRadius: 999 }} /></div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}><span style={{ width: 90, flex: "none" }}>{names[resourceType]}</span><span style={{ display: "block", height: 8, width: earlyHint ? "85%" : "35%", background: accent, borderRadius: 999 }} /></div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}><span style={{ width: 90, flex: "none" }}>Rest of page</span><span style={{ display: "block", height: 8, width: "10%", background: "#24143022", borderRadius: 999 }} /></div>
      <p style={{ margin: "6px 0 0" }}>{earlyHint ? "Requested early, ahead of the elements that need it" : "Requested at normal priority, later in the queue"}</p>
    </div>
  );
}
